    "hero.subtitleStorage": "Salīdzini vietējos noliktavu partnerus pēc platības, cenas un piekļuves. Vai nosūti vienu pieprasījumu un saņem līdz 3 piedāvājumiem — bez maksas un bez saistībām.",
