    "how.step2": "Salīdzināt",
    "how.step2desc": "Filtrējiet rezultātus pēc cenas, atrašanās vietas un vienības veida. Katrā atrašanās vietā redzamas visas pieejamās vienības ar cenām un daudzumiem.",
    "how.step3": "Rezervēt un ietaupīt",
    "how.step3desc": "Atver piemērotu sludinājumu, izvēlies vienības izmēru un nosūti pieprasījumu vai rezervē tiešsaistē, kur partneris to ir iespējojis.",
