    "onboard.step5.notesPlaceholder": "Pievienojiet papildu informāciju par savu pakalpojumu...",
    "onboard.step5.term1": "Ruumly palaišanas laikā pievienošanās partneriem un sludinājumu pievienošana ir bez maksas. Maksas redzamības uzlabojumi vai rīki tiek aktivizēti tikai ar atsevišķu vienošanos.",
