    "provPage.benefit1.desc": "Piesaistiet klientus, kas meklē noliktavas, pārvākšanos un piekabes internetā.",
    "provPage.benefit1.title": "Jauni klienti",
    "provPage.benefit2.desc": "Partnera panelī skati pieprasījumus, sludinājumus, rezervācijas un analītiku tur, kur šīs darba plūsmas ir ieslēgtas.",
    "provPage.benefit2.title": "Ērta pārvaldība",
    "provPage.benefit3.desc": "Sāc bez maksas. Maksas uzlabojumi vai papildu rīki vēlāk ir tikai pēc izvēles un vienošanās.",
    "provPage.benefit3.title": "Elastīgi nosacījumi",
