    "provPage.outcome2.title": "Mazāk telefona zvanu",
    "provPage.outcome2.desc": "Sludinājumi rāda izmērus, cenas, piekļuvi un pieejamību. Klienti atnāk ar labāku kontekstu.",
    "provPage.outcome3.title": "Labāka redzamība Google",
